**`useTelegram.ts`** — hook wrapping the host bridge so the component never touches `window.Telegram` directly

```ts
// useTelegram.ts
import { useEffect, useMemo, useState } from 'react';
import type { TelegramWebApp } from './telegram-webapp';

export function useTelegramWebApp(): TelegramWebApp | null {
  const webApp = useMemo(() => window.Telegram?.WebApp ?? null, []);

  useEffect(() => {
    webApp?.ready();
    webApp?.expand();
  }, [webApp]);

  return webApp;
}

export function useTelegramTheme(webApp: TelegramWebApp | null) {
  const [, forceRender] = useState(0);

  useEffect(() => {
    if (!webApp) return;
    const onChange = () => forceRender((n) => n + 1);
    webApp.onEvent('themeChanged', onChange);
    return () => webApp.offEvent('themeChanged', onChange);
  }, [webApp]);

  return webApp?.themeParams ?? {};
}

export function useBackButton(webApp: TelegramWebApp | null, onBack: () => void) {
  useEffect(() => {
    if (!webApp) return;
    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);
    return () => {
      webApp.BackButton.offClick(onBack);
      webApp.BackButton.hide();
    };
  }, [webApp, onBack]);
}

interface MainButtonOptions {
  text: string;
  enabled: boolean;
  visible: boolean;
  loading: boolean;
  onClick: () => void;
}

export function useMainButton(webApp: TelegramWebApp | null, opts: MainButtonOptions) {
  const { text, enabled, visible, loading, onClick } = opts;

  useEffect(() => {
    if (!webApp) return;
    webApp.MainButton.onClick(onClick);
    return () => webApp.MainButton.offClick(onClick);
  }, [webApp, onClick]);

  useEffect(() => {
    if (!webApp) return;
    webApp.MainButton.setText(text);
    if (visible) webApp.MainButton.show();
    else webApp.MainButton.hide();

    if (loading) webApp.MainButton.showProgress(false);
    else webApp.MainButton.hideProgress();

    if (!loading) {
      if (enabled) webApp.MainButton.enable();
      else webApp.MainButton.disable();
    }
  }, [webApp, text, enabled, visible, loading]);
}

export function useClosingConfirmation(webApp: TelegramWebApp | null, isDirty: boolean) {
  useEffect(() => {
    if (!webApp) return;
    if (isDirty) webApp.enableClosingConfirmation();
    else webApp.disableClosingConfirmation();
    return () => webApp.disableClosingConfirmation();
  }, [webApp, isDirty]);
}
