**`CheckoutScreen.tsx`**

```tsx
// CheckoutScreen.tsx
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  useBackButton,
  useClosingConfirmation,
  useMainButton,
  useTelegramTheme,
  useTelegramWebApp,
} from './useTelegram';
import { CartItem, DeliveryAddress, emptyAddress } from './types';
import './CheckoutScreen.css';

const DELIVERY_FEE = 4.99;

interface CheckoutScreenProps {
  items: CartItem[];
  onBack: () => void;
  onUpdateQuantity: (id: string, quantity: number) => void;
  onRemoveItem: (id: string) => void;
  onPay: (address: DeliveryAddress, total: number) => Promise<void>;
}

type FieldErrors = Partial<Record<keyof DeliveryAddress, string>>;

function validate(address: DeliveryAddress): FieldErrors {
  const errors: FieldErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!/^\+?[0-9\s()-]{7,}$/.test(address.phone.trim())) errors.phone = 'Enter a valid phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street and house number';
  if (!address.postalCode.trim()) errors.postalCode = 'Enter a postal code';
  return errors;
}

export default function CheckoutScreen({
  items,
  onBack,
  onUpdateQuantity,
  onRemoveItem,
  onPay,
}: CheckoutScreenProps) {
  const webApp = useTelegramWebApp();
  const theme = useTelegramTheme(webApp);
  const [address, setAddress] = useState<DeliveryAddress>(emptyAddress);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  useEffect(() => {
    if (!webApp) return;
    const bg = theme.bg_color ? `#${theme.bg_color.replace('#', '')}` : undefined;
    if (bg) {
      webApp.setHeaderColor(bg);
      webApp.setBackgroundColor(bg);
      if (webApp.isVersionAtLeast('7.10') && webApp.setBottomBarColor) {
        webApp.setBottomBarColor(bg);
      }
    }
  }, [webApp, theme]);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = items.length > 0 ? subtotal + DELIVERY_FEE : 0;

  const errors = useMemo(() => validate(address), [address]);
  const isFormValid = Object.keys(errors).length === 0 && items.length > 0;
  const isDirty = useMemo(
    () => Object.values(address).some((value) => value.trim() !== ''),
    [address]
  );

  useClosingConfirmation(webApp, isDirty && !submitting);
  useBackButton(webApp, onBack);

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const handlePay = useCallback(async () => {
    if (!isFormValid || submitting) return;
    webApp?.HapticFeedback.impactOccurred('medium');
    setSubmitError(null);
    setSubmitting(true);
    webApp?.hideKeyboard?.();
    try {
      await onPay(address, total);
      webApp?.HapticFeedback.notificationOccurred('success');
    } catch (err) {
      webApp?.HapticFeedback.notificationOccurred('error');
      setSubmitError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
    } finally {
      setSubmitting(false);
    }
  }, [address, isFormValid, onPay, submitting, total, webApp]);

  useMainButton(webApp, {
    text: items.length > 0 ? `Pay $${total.toFixed(2)}` : 'Your cart is empty',
    enabled: isFormValid,
    visible: true,
    loading: submitting,
    onClick: handlePay,
  });

  const errorFor = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout">
      {!webApp && (
        <button type="button" className="checkout__fallback-back" onClick={onBack} aria-label="Back to cart">
          ← Back to cart
        </button>
      )}

      <h1 className="checkout__title">Checkout</h1>

      <section className="checkout__section" aria-label="Cart items">
        <h2 className="checkout__section-title">Your order</h2>

        {items.length === 0 ? (
          <p className="checkout__empty">Your cart is empty.</p>
        ) : (
          <ul className="cart-list">
            {items.map((item) => (
              <li className="cart-item" key={item.id}>
                {item.imageUrl ? (
                  <img className="cart-item__image" src={item.imageUrl} alt={item.name} />
                ) : (
                  <div className="cart-item__image cart-item__image--placeholder" aria-hidden="true" />
                )}

                <div className="cart-item__info">
                  <span className="cart-item__name">{item.name}</span>
                  <span className="cart-item__price">${item.price.toFixed(2)}</span>
                </div>

                <div className="cart-item__controls">
                  <div className="quantity-stepper">
                    <button
                      type="button"
                      className="quantity-stepper__btn"
                      aria-label={`Decrease quantity of ${item.name}`}
                      onClick={() =>
                        item.quantity > 1
                          ? onUpdateQuantity(item.id, item.quantity - 1)
                          : onRemoveItem(item.id)
                      }
                    >
                      −
                    </button>
                    <span className="quantity-stepper__value" aria-live="polite">
                      {item.quantity}
                    </span>
                    <button
                      type="button"
                      className="quantity-stepper__btn"
                      aria-label={`Increase quantity of ${item.name}`}
                      onClick={() => onUpdateQuantity(item.id, item.quantity + 1)}
                    >
                      +
                    </button>
                  </div>
                  <button
                    type="button"
                    className="cart-item__remove"
                    aria-label={`Remove ${item.name} from cart`}
                    onClick={() => onRemoveItem(item.id)}
                  >
                    Remove
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}

        {items.length > 0 && (
          <div className="checkout__totals">
            <div className="checkout__totals-row">
              <span>Subtotal</span>
              <span>${subtotal.toFixed(2)}</span>
            </div>
            <div className="checkout__totals-row">
              <span>Delivery</span>
              <span>${DELIVERY_FEE.toFixed(2)}</span>
            </div>
            <div className="checkout__totals-row checkout__totals-row--total">
              <span>Total</span>
              <span>${total.toFixed(2)}</span>
            </div>
          </div>
        )}
      </section>

      <section className="checkout__section" aria-label="Delivery address">
        <h2 className="checkout__section-title">Delivery address</h2>

        <form className="address-form" onSubmit={(e) => e.preventDefault()}>
          <label className="field">
            <span className="field__label">Full name</span>
            <input
              className="field__input"
              type="text"
              name="fullName"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange('fullName')}
              onBlur={handleBlur('fullName')}
              aria-invalid={Boolean(errorFor('fullName'))}
            />
            {errorFor('fullName') && <span className="field__error">{errorFor('fullName')}</span>}
          </label>

          <label className="field">
            <span className="field__label">Phone number</span>
            <input
              className="field__input"
              type="tel"
              name="phone"
              autoComplete="tel"
              value={address.phone}
              onChange={handleChange('phone')}
              onBlur={handleBlur('phone')}
              aria-invalid={Boolean(errorFor('phone'))}
            />
            {errorFor('phone') && <span className="field__error">{errorFor('phone')}</span>}
          </label>

          <label className="field">
            <span className="field__label">City</span>
            <input
              className="field__input"
              type="text"
              name="city"
              autoComplete="address-level2"
              value={address.city}
              onChange={handleChange('city')}
              onBlur={handleBlur('city')}
              aria-invalid={Boolean(errorFor('city'))}
            />
            {errorFor('city') && <span className="field__error">{errorFor('city')}</span>}
          </label>

          <label className="field">
            <span className="field__label">Street and house number</span>
            <input
              className="field__input"
              type="text"
              name="street"
              autoComplete="address-line1"
              value={address.street}
              onChange={handleChange('street')}
              onBlur={handleBlur('street')}
              aria-invalid={Boolean(errorFor('street'))}
            />
            {errorFor('street') && <span className="field__error">{errorFor('street')}</span>}
          </label>

          <div className="field-row">
            <label className="field">
              <span className="field__label">Apartment (optional)</span>
              <input
                className="field__input"
                type="text"
                name="apartment"
                autoComplete="address-line2"
                value={address.apartment}
                onChange={handleChange('apartment')}
              />
            </label>

            <label className="field">
              <span className="field__label">Postal code</span>
              <input
                className="field__input"
                type="text"
                name="postalCode"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={handleChange('postalCode')}
                onBlur={handleBlur('postalCode')}
                aria-invalid={Boolean(errorFor('postalCode'))}
              />
              {errorFor('postalCode') && (
                <span className="field__error">{errorFor('postalCode')}</span>
              )}
            </label>
          </div>

          <label className="field">
            <span className="field__label">Delivery notes (optional)</span>
            <textarea
              className="field__input field__textarea"
              name="comment"
              rows={3}
              value={address.comment}
              onChange={handleChange('comment')}
            />
          </label>
        </form>
      </section>

      {submitError && (
        <p className="checkout__submit-error" role="alert">
          {submitError}
        </p>
      )}

      {!webApp && (
        <button
          type="button"
          className="checkout__fallback-pay"
          disabled={!isFormValid || submitting}
          onClick={handlePay}
        >
          {submitting ? 'Processing…' : `Pay $${total.toFixed(2)}`}
        </button>
      )}
    </div>
  );
}
```

